"""Topic path subscription matcher."""

def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    """
    Determines if an event topic matches a subscription pattern based on hierarchical
    access control rules (Rule H06).

    - Double-colon `::` separates segments.
    - Single asterisk `*` matches exactly one segment.
    - Double asterisk `**` matches zero or more segments at the end of a pattern.
    """
    pattern_segments = subscribed_pattern.split("::")
    topic_segments = event_topic.split("::")

    # Handle the special case where the pattern is just "**"
    if subscribed_pattern == "**":
        return True

    # Check for "**" at the end of the pattern
    if pattern_segments and pattern_segments[-1] == "**":
        # The "**" matches zero or more segments.
        # All segments before "**" must match exactly or with a single "*" wildcard.
        prefix_pattern_segments = pattern_segments[:-1]

        # The topic must have at least as many segments as the non-"**" prefix pattern
        if len(topic_segments) < len(prefix_pattern_segments):
            return False

        # Compare prefix segments
        for i in range(len(prefix_pattern_segments)):
            if prefix_pattern_segments[i] == "*":
                # "*" matches exactly one segment, which is implicitly handled by the loop structure
                continue
            elif prefix_pattern_segments[i] != topic_segments[i]:
                return False
        return True  # Prefix matched, "**" covers the rest

    # If no "**" at the end, then the number of segments must match exactly
    if len(pattern_segments) != len(topic_segments):
        return False

    # Segment by segment comparison
    for p_segment, t_segment in zip(pattern_segments, topic_segments):
        if p_segment == "*":
            # "*" matches exactly one segment (its presence in the loop implies this)
            continue
        elif p_segment != t_segment:
            return False

    return True

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
